let PORTRAITS={"ag_prim":"data:image/jpeg;base64,","ag_poppy":"data:image/jpeg;base64,","ag_prawn":"data:image/jpeg;base64,","npc_dengler":"data:image/jpeg;base64,","npc_peak":"data:image/jpeg;base64,","npc_santorini":"data:image/jpeg;base64,","npc_debbie":"data:image/jpeg;base64,","npc_luigi":"data:image/jpeg;base64,","npc_paulie":"data:image/jpeg;base64,","npc_johnsonson":"data:image/jpeg;base64,","npc_greg":"data:image/jpeg;base64,","npc_sue":"data:image/jpeg;base64,","npc_therapist":"data:image/jpeg;base64,","npc_expartner":"data:image/jpeg;base64,","npc_phenx":"data:image/jpeg;base64,"};
const SKEY="dg-pcell-v3";
// Load from Supabase, fall back to localStorage, then preloaded defaults
async function loadDataFromSupabase(){
try{
const{data:ops,error:opsErr}=await supabase.from("operations").select("*");
const{data:chars,error:charsErr}=await supabase.from("personnel").select("*");
if(opsErr||charsErr)throw new Error("DB error");
if(ops&&ops.length>0){
// Data exists in Supabase
const operations=ops.map(r=>({...r.data,_dbId:r.id}));
const agents=chars?chars.map(r=>({...r.data,_dbId:r.id,_isPublic:r.is_public})):[];
return{operations,agents};
}
// Supabase is empty — check localStorage for migrateable data
const local=localStorage.getItem(SKEY);
if(local){
const parsed=JSON.parse(local);
if(parsed&&parsed.operations&&parsed.operations.length>0)return{...parsed,_needsSeed:true};
}
// Nothing anywhere — use preloaded defaults and seed
return{operations:PRELOADED_OPS,agents:PRELOADED_AG,_needsSeed:true};
}catch(e){
console.error("Load error:",e);
// Offline fallback to localStorage
try{const d=localStorage.getItem(SKEY);if(d)return JSON.parse(d)}catch(e2){}
return{operations:PRELOADED_OPS,agents:PRELOADED_AG,_needsSeed:true};
}
}
// Seed Supabase with initial data
async function seedSupabase(operations,agents){
for(const op of operations){
const{error:soe}=await supabase.from("operations").upsert({op_id:op.id,data:op},{onConflict:"op_id"});if(soe)console.error("Seed op error:",soe);
}
for(const ag of agents){
const isPublic=!ag.isNPC&&!ag.isBond;
const{error:spe}=await supabase.from("personnel").upsert({char_id:ag.id,data:ag,is_public:isPublic},{onConflict:"char_id"});if(spe)console.error("Seed personnel error:",spe);
}
}
// Save a single operation to Supabase
async function saveOperation(op){
const clean={...op};delete clean._dbId;
const{error}=await supabase.from("operations").upsert({op_id:op.id,data:clean},{onConflict:"op_id"});
if(error)console.error("Save op error:",error);
// Also save to localStorage as backup
try{const d=JSON.parse(localStorage.getItem(SKEY)||"{}");const ops=(d.operations||[]).map(o=>o.id===op.id?op:o);if(!ops.find(o=>o.id===op.id))ops.push(op);localStorage.setItem(SKEY,JSON.stringify({...d,operations:ops}))}catch(e){}
}
// Save a single personnel to Supabase
async function savePersonnel(ag){
const clean={...ag};delete clean._dbId;delete clean._isPublic;
const isPublic=ag.isNPC&&!ag.isBond?(ag._isPublic||false):true;
const{error}=await supabase.from("personnel").upsert({char_id:ag.id,data:clean,is_public:isPublic},{onConflict:"char_id"});
if(error)console.error("Save personnel error:",error);
try{const d=JSON.parse(localStorage.getItem(SKEY)||"{}");const ags=(d.agents||[]).map(a=>a.id===ag.id?ag:a);if(!ags.find(a=>a.id===ag.id))ags.push(ag);localStorage.setItem(SKEY,JSON.stringify({...d,agents:ags}))}catch(e){}
}
// Delete from Supabase
async function deleteOperation(opId){
const{error}=await supabase.from("operations").delete().eq("op_id",opId);
if(error)console.error("Delete op error:",error);
}
async function deletePersonnel(charId){
const{error}=await supabase.from("personnel").delete().eq("char_id",charId);
if(error)console.error("Delete personnel error:",error);
}

const F={d:"'Special Elite','Courier New',monospace",b:"'EB Garamond','Georgia',serif",m:"'Courier New',monospace"};
const C={bg:"#1e1e16",bgD:"#14140e",bgC:"#1a1a14",br:"#2a2a1e",brL:"#3a3a2e",t:"#d4c9a8",tS:"#8b7d5e",tD:"#6b6347",tF:"#4a4a3e",ac:"#5e6b4a",aW:"#8b6b2e",g:"#c9a84a",dn:"#8b4040",dB:"#c94a4a"};
function useIsMobile(bp=768){const[m,setM]=useState(typeof window!=="undefined"&&window.innerWidth<bp);useEffect(()=>{const h=()=>setM(window.innerWidth<bp);window.addEventListener("resize",h);return()=>window.removeEventListener("resize",h)},[bp]);return m}
const getPortrait=(agent)=>agent.portrait||PORTRAITS[agent.id]||null;

function CH({label}){return <div style={{display:"flex",alignItems:"center",gap:12,margin:"8px 0 16px"}}><div style={{flex:1,height:1,background:C.brL}}/><span style={{fontFamily:F.d,fontSize:11,letterSpacing:4,color:C.tS,textTransform:"uppercase"}}>{label}</span><div style={{flex:1,height:1,background:C.brL}}/></div>}
function Stamp({text,color="#6b2020"}){return <span style={{fontFamily:F.d,fontSize:12,fontWeight:700,color,border:`2px solid ${color}`,padding:"2px 8px",borderRadius:3,transform:"rotate(-3deg)",display:"inline-block",letterSpacing:3,textTransform:"uppercase",opacity:0.85}}>{text}</span>}
function Btn({children,onClick,danger,small,active}){return <button onClick={onClick} style={{fontFamily:F.d,fontSize:small?10:11,letterSpacing:2,textTransform:"uppercase",color:danger?"#c47":active?C.t:C.tS,background:active?C.brL:"transparent",border:`1px solid ${danger?C.dn:C.brL}`,padding:small?"3px 8px":"6px 14px",cursor:"pointer",borderRadius:2}}>{children}</button>}
function Field({label,value,onChange,multiline,placeholder,mono}){const s={fontFamily:mono?F.m:F.b,fontSize:mono?13:15,color:C.t,background:C.bgC,border:`1px solid ${C.brL}`,padding:"8px 10px",width:"100%",borderRadius:2,outline:"none",lineHeight:1.6,boxSizing:"border-box"};
const tRef=useRef(null);
const autoSize=el=>{if(el){el.style.height="auto";el.style.height=el.scrollHeight+"px"}};
useEffect(()=>{if(multiline&&tRef.current)autoSize(tRef.current)},[value]);
return <div style={{marginBottom:12}}>{label&&<label style={{fontFamily:F.d,fontSize:10,letterSpacing:2,color:C.tD,textTransform:"uppercase",display:"block",marginBottom:4}}>{label}</label>}{multiline?<textarea ref={tRef} value={value} onChange={e=>{onChange(e.target.value);autoSize(e.target)}} placeholder={placeholder} rows={2} style={{...s,resize:"none",overflow:"hidden"}}/>:<input value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} style={s}/>}</div>}
function Tag({text,onRemove,onEdit}){const[editing,setEditing]=useState(false);const[val,setVal]=useState(text);
if(editing)return <span style={{display:"inline-flex",alignItems:"center",gap:4,margin:"2px 4px 2px 0"}}><input value={val} onChange={e=>setVal(e.target.value)} onBlur={()=>{if(val.trim()){onEdit(val.trim())}setEditing(false)}} onKeyDown={e=>{if(e.key==="Enter"){if(val.trim())onEdit(val.trim());setEditing(false)}}} autoFocus style={{fontFamily:F.m,fontSize:12,color:C.t,background:C.bgC,border:`1px solid ${C.ac}`,padding:"3px 8px",borderRadius:2,outline:"none",width:160}}/></span>;
return <span style={{display:"inline-flex",alignItems:"center",gap:6,fontFamily:F.m,fontSize:12,color:C.t,background:"#2a2a1e",border:`1px solid ${C.brL}`,padding:"3px 8px",borderRadius:2,margin:"2px 4px 2px 0",cursor:onEdit?"pointer":"default"}} onClick={()=>onEdit&&setEditing(true)}>{text}{onRemove&&<span onClick={e=>{e.stopPropagation();onRemove()}} style={{cursor:"pointer",color:C.dn,fontWeight:700}}>×</span>}</span>}
function TagList({label,items,onAdd,onRemove,onEdit,placeholder}){const[v,setV]=useState("");const add=()=>{if(v.trim()){onAdd(v.trim());setV("")}};return <div style={{marginBottom:12}}><label style={{fontFamily:F.d,fontSize:10,letterSpacing:2,color:C.tD,textTransform:"uppercase",display:"block",marginBottom:4}}>{label}</label><div style={{display:"flex",gap:6,marginBottom:6}}><input value={v} onChange={e=>setV(e.target.value)} onKeyDown={e=>e.key==="Enter"&&add()} placeholder={placeholder} style={{flex:1,fontFamily:F.m,fontSize:13,color:C.t,background:C.bgC,border:`1px solid ${C.brL}`,padding:"6px 10px",borderRadius:2,outline:"none"}}/><Btn small onClick={add}>+</Btn></div><div style={{display:"flex",flexWrap:"wrap"}}>{items.map((t,i)=><Tag key={i} text={t} onRemove={()=>onRemove(i)} onEdit={onEdit?(val)=>onEdit(i,val):undefined}/>)}</div></div>}
function StatBlock({stats,derived,current,onChange,onCD,onCC}){return <div style={{marginBottom:16}}><div style={{display:"flex",gap:8,flexWrap:"wrap"}}>{STAT_LABELS.map(s=><div key={s} style={{textAlign:"center",width:52}}><div style={{fontFamily:F.d,fontSize:9,letterSpacing:2,color:C.tD,marginBottom:2}}>{s}</div><input value={stats[s]} onChange={e=>onChange(s,+e.target.value||0)} style={{width:48,textAlign:"center",fontFamily:F.m,fontSize:16,fontWeight:700,color:C.t,background:C.bgC,border:`1px solid ${C.brL}`,padding:"4px 0",borderRadius:2,outline:"none"}}/></div>)}</div><div style={{display:"flex",gap:8,flexWrap:"wrap",marginTop:8,marginBottom:14}}>{STAT_LABELS.map(s=><div key={s} style={{textAlign:"center",width:52}}><div style={{fontFamily:F.d,fontSize:11,letterSpacing:2,color:C.tS,marginBottom:2}}>×5</div><div style={{width:48,textAlign:"center",fontFamily:F.m,fontSize:16,fontWeight:700,color:C.tD,background:"#151510",border:`1px solid ${C.br}`,padding:"4px 0",borderRadius:2,margin:"0 auto",opacity:0.7}}>{stats[s]*5}</div></div>)}</div><div style={{display:"flex",gap:12,flexWrap:"wrap"}}>{DERIVED_LABELS.map(s=><div key={s} style={{textAlign:"center",width:72}}><div style={{fontFamily:F.d,fontSize:9,letterSpacing:2,color:s==="SAN"?C.aW:C.tD,marginBottom:2}}>{s}</div><div style={{display:"flex",alignItems:"center",justifyContent:"center",gap:2}}><input value={current[s]} onChange={e=>onCC(s,+e.target.value||0)} style={{width:32,textAlign:"center",fontFamily:F.m,fontSize:15,fontWeight:700,color:current[s]<derived[s]?C.dB:s==="SAN"?C.g:C.t,background:C.bgC,border:`1px solid ${s==="SAN"?"#5a4a2e":C.brL}`,padding:"4px 0",borderRadius:2,outline:"none"}}/><span style={{color:C.tF,fontSize:10}}>/</span><input value={derived[s]} onChange={e=>onCD(s,+e.target.value||0)} style={{width:32,textAlign:"center",fontFamily:F.m,fontSize:13,color:C.tD,background:C.bgC,border:`1px solid ${C.brL}`,padding:"4px 0",borderRadius:2,outline:"none"}}/></div></div>)}</div></div>}
function SkillAdder({onAdd}){const[show,setShow]=useState(false);const[name,setName]=useState("");const[base,setBase]=useState(0);const doAdd=()=>{if(name.trim()){onAdd(name.trim(),+base||0);setName("");setBase(0);setShow(false)}};if(!show)return <Btn small onClick={()=>setShow(true)}>+ Skill</Btn>;return <div style={{display:"flex",gap:6,alignItems:"center",marginBottom:8}}><input value={name} onChange={e=>setName(e.target.value)} onKeyDown={e=>e.key==="Enter"&&doAdd()} placeholder="Skill name" autoFocus style={{flex:1,fontFamily:F.m,fontSize:12,color:C.t,background:C.bgC,border:`1px solid ${C.brL}`,padding:"5px 8px",borderRadius:2,outline:"none"}}/><input value={base} onChange={e=>setBase(e.target.value)} onKeyDown={e=>e.key==="Enter"&&doAdd()} placeholder="Base" style={{width:44,fontFamily:F.m,fontSize:12,color:C.tF,background:C.bgC,border:`1px solid ${C.brL}`,padding:"5px 4px",borderRadius:2,outline:"none",textAlign:"center"}}/><Btn small onClick={doAdd}>Add</Btn><span onClick={()=>{setShow(false);setName("");setBase(0)}} style={{cursor:"pointer",color:C.tD,fontSize:14}}>×</span></div>}
function BondsEd({bonds,onChange}){const u=(i,f,v)=>{const b=[...bonds];b[i]={...b[i],[f]:v};onChange(b)};return <div style={{marginBottom:12}}><label style={{fontFamily:F.d,fontSize:10,letterSpacing:2,color:C.tD,textTransform:"uppercase",display:"block",marginBottom:6}}>Bonds</label>{bonds.map((b,i)=><div key={i} style={{display:"flex",gap:6,marginBottom:4,alignItems:"center"}}><input value={b.name} onChange={e=>u(i,"name",e.target.value)} placeholder="Bond" style={{flex:1,fontFamily:F.m,fontSize:13,color:C.t,background:C.bgC,border:`1px solid ${C.brL}`,padding:"5px 8px",borderRadius:2,outline:"none"}}/><input value={b.score} onChange={e=>u(i,"score",+e.target.value||0)} style={{width:44,textAlign:"center",fontFamily:F.m,fontSize:14,fontWeight:700,color:C.t,background:C.bgC,border:`1px solid ${C.brL}`,padding:"5px 0",borderRadius:2,outline:"none"}}/><span onClick={()=>{const b2=[...bonds];b2.splice(i,1);onChange(b2)}} style={{cursor:"pointer",color:C.dn,fontSize:16}}>×</span></div>)}{bonds.length<4&&<Btn small onClick={()=>onChange([...bonds,{name:"",score:10}])}>+ Bond</Btn>}</div>}

